import sys

def main():
    data = sys.stdin.read().split()
    n, limit, window = int(data[0]), int(data[1]), int(data[2])
    groups = {}
    bad = [False] * n
    for i in range(n):
        name, t, amt, city = data[3 + 4 * i], int(data[4 + 4 * i]), int(data[5 + 4 * i]), data[6 + 4 * i]
        if amt > limit:
            bad[i] = True
        groups.setdefault(name, []).append((t, city, i))
    for lst in groups.values():
        lst.sort()
        m = len(lst)
        cnt = {}
        lo = hi = 0
        for j in range(m):
            t = lst[j][0]
            while hi < m and lst[hi][0] <= t + window:
                c = lst[hi][1]
                cnt[c] = cnt.get(c, 0) + 1
                hi += 1
            while lst[lo][0] < t - window:
                c = lst[lo][1]
                cnt[c] -= 1
                if cnt[c] == 0:
                    del cnt[c]
                lo += 1
            if len(cnt) >= 2:
                bad[lst[j][2]] = True
    res = [str(i) for i in range(n) if bad[i]]
    print(' '.join(res) if res else 'NONE')

main()

